def components(order: int, edges: AbstractSet[tuple[int, int]], deleted: set[int]) -> int:
    remaining = set(range(order)) - deleted
    count = 0
    while remaining:
        count += 1
        stack = [remaining.pop()]
        while stack:
            u = stack.pop()
            found = {v for v in remaining if (min(u,v), max(u,v)) in edges}
            remaining -= found
            stack.extend(found)
    return count

def toughness_witness(order: int, edges: AbstractSet[tuple[int, int]]) -> Optional[tuple[set[int], int]]:
    for size in range(order + 1):
        for choice in combinations(range(order), size):
            deleted = set(choice)
            count = components(order, edges, deleted)
            if count > 1 and count > size:
                return deleted, count
    return None

